    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceFlowShareEventListener = UniffiVTableCallbackInterfaceFlowShareEventListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
